2	
3	const NEIGHBOR_OFFSETS: ReadonlyArray<Cell> = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [ 0, -1],          [ 0, 1],
6	  [ 1, -1], [ 1, 0], [ 1, 1],
7	];
8	
9	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const cellFromKey = (key: string): Cell => {
12	  const [x, y] = key.split(",").map(Number);
13	  return [x, y];
14	};
15	
16	const willBeAlive = (isAlive: boolean, neighbors: number): boolean =>
17	  neighbors === 3 || (isAlive && neighbors === 2);
18	
19	const neighborsOf = ([x, y]: Cell): Cell[] =>
20	  NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
21	
22	export function nextGeneration(liveCells: Cell[]): Cell[] {
23	  const alive = new Set(liveCells.map(cellKey));
24	  const neighborCounts = new Map<string, number>();
25	
26	  for (const cell of liveCells) {
27	    for (const neighbor of neighborsOf(cell)) {
28	      const key = cellKey(neighbor);
29	      neighborCounts.set(key, (neighborCounts.get(key) ?? 0) + 1);
30	    }
31	  }
32	
33	  return [...neighborCounts]
34	    .filter(([key, count]) => willBeAlive(alive.has(key), count))
35	    .map(([key]) => cellFromKey(key));
36	}
